package com.google.javascript.rhino;

import com.google.common.base.Preconditions;
import com.google.javascript.rhino.IR;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class IR_tryFinally_TriageGen1Test {



    @Test(expected = IllegalStateException.class)
    public void testTryFinally_TryBodyNotLabelNameThrows() {
        // tryBody is a regular block, not a label name
        Node tryBody = IR.block();
        Node finallyBody = IR.labelName("finallyLabel");

        IR.tryFinally(tryBody, finallyBody);
    }




}

